import itertools, sys, json
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
Lset = set(L)
used = set()
solution = []

# Precompute all possible triples (a,b,c) with a<b and a+b=c
triples = []
for a,b in itertools.combinations(L,2):
    c = a+b
    if c in Lset and c!=a and c!=b:
        triples.append((a,b,c))

# Simple backtracking
def backtrack(start, current_used, current_sol):
    if len(current_sol) == 15:
        return current_sol
    for idx in range(start, len(triples)):
        a,b,c = triples[idx]
        if a in current_used or b in current_used or c in current_used:
            continue
        new_used = current_used | {a,b,c}
        res = backtrack(idx+1, new_used, current_sol+[(a,b,c)])
        if res:
            return res
    return None

sol = backtrack(0, set(), [])
if sol:
    print("Solution found:")
    for triple in sol:
        print(triple)
    witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":{"partition":sol}}
else:
    print("No solution")
    witness = {"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"proof","argument":"Exhaustive search found no valid partition."}
print("WITNESS:", json.dumps(witness))
